using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a default resolver (reflection-based)
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");
Console.WriteLine($"  Properties: {personInfo.Properties.Count}");

// Serialize using the typed info to prove it works
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if not resolvable
// Use a resolver that only handles Person — Widget will fail gracefully.
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? foundInfo))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {foundInfo!.Type.Name}");
}

if (limitedOptions.TryGetTypeInfo(typeof(Widget), out JsonTypeInfo? widgetInfo))
{
    Console.WriteLine($"TryGetTypeInfo(Widget) succeeded (unexpected)");
}
else
{
    Console.WriteLine($"\nTryGetTypeInfo(Widget) returned false — no exception thrown.");
}

// --- Types ---
record Person(string Name, int Age);
record Widget(string Sku);

// A custom resolver that only resolves Person
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);

        return null; // signal "not supported"
    }
}

